const item = $input.first();
const body = item.json.body || {};

const sessionId = body.sessionId;
const laudoId = `LAUDO-${Date.now()}-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;

return [{
  json: {
    sessionId,
    laudoId,
    imovel: body.imovel || 'Não identificado',
    tipo: body.tipo || 'entrada',
    endereco: body.endereco || '—',
    proprietario: body.proprietario || '—',
    inquilino: body.inquilino || '—',
    dataVistoria: body.dataVistoria || new Date().toISOString(),
    obs: body.obs || '',
    totalVideos: parseInt(body.totalVideos) || 0,
    laudo_url: `https://inspections.example.com/laudo/${laudoId}`
  }
}];

const item = $input.first().json;
const sessionId = item.sessionId;
const sessionPath = `/data/inspections/sessions/${sessionId}`;

// Criar placeholder HTML
const placeholderHtml = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta http-equiv="refresh" content="30">
<title>Processando Laudo...</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { font-family: 'Inter', sans-serif; background: #141416; color: #f0f0f0; display: flex; align-items: center; justify-content: center; min-height: 100vh; }
  .container { text-align: center; padding: 40px; max-width: 500px; }
  .spinner { width: 64px; height: 64px; border: 3px solid #2a2a2e; border-top-color: #c9a96e; border-radius: 50%; animation: spin 1.2s linear infinite; margin: 0 auto 24px; }
  @keyframes spin { to { transform: rotate(360deg); } }
  h1 { font-size: 22px; margin-bottom: 12px; color: #c9a96e; }
  p { font-size: 14px; color: #a0a0a4; line-height: 1.8; }
  .info { margin-top: 24px; padding: 16px; background: #1e2023; border-radius: 12px; border: 1px solid #2a2a2e; }
  .info p { font-size: 12px; color: #6a6a6e; }
</style>
</head>
<body>
<div class="container">
  <div class="spinner"></div>
  <h1>Processando Vistoria</h1>
  <p>O laudo está sendo gerado pela IA.<br>Esta página atualiza automaticamente a cada 30 segundos.</p>
  <div class="info">
    <p>Imóvel: ${item.imovel} · ${item.tipo}<br>Vídeos: ${item.totalVideos}<br>Início: ${new Date().toLocaleTimeString('pt-BR')}</p>
  </div>
</div>
</body>
</html>`;

return [{
  json: {
    ...item,
    sessionPath,
    placeholderHtml
  },
  binary: {
    placeholder: {
      data: Buffer.from(placeholderHtml, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName: `${item.laudoId}.html`
    }
  }
}];

const fs = require('fs');
const path = require('path');

const item = $input.first().json;
const sessionPath = item.sessionPath;

// Listar arquivos de vídeo na pasta da sessão
let videoFiles = [];
try {
  const files = fs.readdirSync(sessionPath);
  videoFiles = files
    .filter(f => f.endsWith('.mp4') || f.endsWith('.mov') || f.endsWith('.avi') || f.endsWith('.webm'))
    .sort()
    .map(f => ({
      fileName: f,
      filePath: path.join(sessionPath, f)
    }));
} catch (e) {
  return [{ json: { error: `Erro ao ler sessão: ${e.message}`, sessionPath } }];
}

// Criar um item para cada vídeo
const outputItems = videoFiles.map((vf, idx) => ({
  json: {
    idImovel: item.imovel,
    imovel: item.imovel,
    tipoVistoria: item.tipo,
    endereco: item.endereco,
    proprietario: item.proprietario,
    inquilino: item.inquilino,
    dataVistoria: item.dataVistoria,
    observacoesGeraisWebhook: item.obs,
    originalFileName: vf.fileName,
    filePath: vf.filePath,
    videoIndex: idx,
    totalVideos: videoFiles.length,
    laudoId: item.laudoId,
    laudo_url: item.laudo_url,
    sessionId: item.sessionId
  }
}));

if (outputItems.length === 0) {
  return [{ json: { ...item, error: 'Nenhum vídeo encontrado na sessão', videoFiles: [] } }];
}

return outputItems;

const response = $input.first().json;

let textoGemini = '';
if (response.candidates && response.candidates[0]?.content?.parts[0]?.text) {
  textoGemini = response.candidates[0].content.parts[0].text;
}

let jsonText = textoGemini.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let dadosVistoria;
try {
  dadosVistoria = JSON.parse(jsonText);
} catch (e) {
  dadosVistoria = {
    comodos: [],
    observacoes_gerais: 'Erro ao parsear: ' + e.message,
    problemas_criticos: [],
    parse_error: true
  };
}

if (dadosVistoria.comodos && dadosVistoria.comodos.length > 0) {
  const comodosMesclados = {};

  for (const comodo of dadosVistoria.comodos) {
    const nome = comodo.nome;

    if (comodosMesclados[nome]) {
      comodosMesclados[nome].itens = [
        ...comodosMesclados[nome].itens,
        ...comodo.itens
      ];
      if (comodo.timestamp_fim > comodosMesclados[nome].timestamp_fim) {
        comodosMesclados[nome].timestamp_fim = comodo.timestamp_fim;
      }
    } else {
      comodosMesclados[nome] = { ...comodo };
    }
  }

  dadosVistoria.comodos = Object.values(comodosMesclados);
}

const prevData = $('Limpar Binário').first().json;

return [{
  json: {
    imovel: prevData.imovel || '',
    tipoVistoria: prevData.tipoVistoria || '',
    endereco: prevData.endereco || '',
    proprietario: prevData.proprietario || '',
    inquilino: prevData.inquilino || '',
    dataVistoria: prevData.dataVistoria || '',
    observacoesGeraisWebhook: prevData.observacoesGeraisWebhook || '',
    originalFileName: prevData.originalFileName || '',
    laudoId: prevData.laudoId || '',
    laudo_url: prevData.laudo_url || '',
    resultado_analise: dadosVistoria
  }
}];

const inputItem = $input.first().json;
const dadosAnalise = inputItem.resultado_analise || {};

const prompt = `Você é um especialista em laudos de vistorias imobiliárias no Brasil. Recebeu os dados brutos extraídos por IA de um vídeo de vistoria.

Sua tarefa é:
1. **DEDUPLICAR AMBIENTES**: Se houver dois ou mais ambientes com o mesmo nome ou nomes muito similares (ex: "Sala de Estar" aparecendo 2x, ou "Banheiro" e "Banheiro Social" descrevendo o MESMO cômodo), MESCLE-OS em uma única entrada, consolidando todos os itens.
2. **CONSOLIDAR GARAGEM/ÁREA EXTERNA**: Se a garagem estiver dividida em múltiplas entradas (interior, piso externo, rampa), unifique em um único ambiente "Garagem" com todos os itens listados.
3. Revisar e padronizar a linguagem (formal, técnica, clara)
4. Corrigir inconsistências na classificação de estados
5. Garantir que as descrições sejam objetivas e juridicamente úteis
6. Formatar o texto final de forma padronizada

REGRAS DE DEDUPLICAÇÃO:
- Se dois ambientes têm o mesmo nome → mesclar em um só, somando os itens
- Se dois ambientes descrevem claramente o MESMO espaço físico (mesmo piso, mesmas paredes) → mesclar
- Se são espaços DIFERENTES com nome similar → renomear para diferenciar (ex: "Sala de Estar (Frente)" e "Sala de TV (Fundos)")
- O array final "comodos" NÃO PODE ter nomes duplicados

Dados brutos:
${JSON.stringify(dadosAnalise)}

Retorne o JSON refinado mantendo a MESMA ESTRUTURA. Retorne APENAS o JSON, sem markdown.`;

return [{
  json: {
    ...inputItem,
    gemini_refinement_body: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.2, maxOutputTokens: 65536 }
    }
  }
}];

const response = $input.first().json;
const prevData = $('Preparar Refinamento').first().json;

let textoRefinado = '';
if (response.candidates && response.candidates[0]?.content?.parts[0]?.text) {
  textoRefinado = response.candidates[0].content.parts[0].text;
}

let jsonText = textoRefinado.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let laudoRefinado;
try {
  laudoRefinado = JSON.parse(jsonText);
} catch (e) {
  laudoRefinado = prevData.resultado_analise || { comodos: [], observacoes_gerais: '', problemas_criticos: [] };
}

return [{
  json: {
    imovel: prevData.imovel,
    tipoVistoria: prevData.tipoVistoria,
    endereco: prevData.endereco,
    proprietario: prevData.proprietario,
    inquilino: prevData.inquilino,
    dataVistoria: prevData.dataVistoria,
    observacoesGeraisWebhook: prevData.observacoesGeraisWebhook,
    originalFileName: prevData.originalFileName,
    laudoId: prevData.laudoId,
    laudo_url: prevData.laudo_url,
    dados_refinados: laudoRefinado
  }
}];

// Salvar resultado do vídeo e voltar ao loop
const item = $input.first().json;

return [{ json: item }];

// Consolidar todos os resultados dos vídeos processados
const allItems = $input.all();

const firstItem = allItems[0].json;
const laudoId = firstItem.laudoId;
const laudo_url = firstItem.laudo_url;

let finalLaudo = {
  laudo_id: laudoId,
  imovel: firstItem.imovel,
  tipoVistoria: firstItem.tipoVistoria,
  dataVistoria: firstItem.dataVistoria,
  data_processamento: new Date().toISOString(),
  endereco: firstItem.endereco,
  proprietario: firstItem.proprietario,
  inquilino: firstItem.inquilino,
  laudo_url: laudo_url,
  observacoes_gerais: '',
  problemas_criticos: [],
  dados_refinados: { comodos: [] }
};

const obsSet = new Set();
const probSet = new Set();

allItems.forEach(item => {
  const dados = item.json.dados_refinados;
  if (dados) {
    if (dados.comodos) {
      finalLaudo.dados_refinados.comodos = finalLaudo.dados_refinados.comodos.concat(dados.comodos);
    }
    if (dados.observacoes_gerais && dados.observacoes_gerais.trim()) {
      obsSet.add(dados.observacoes_gerais.trim());
    }
    if (dados.problemas_criticos) {
      dados.problemas_criticos.forEach(p => probSet.add(p));
    }
  }
});

finalLaudo.observacoes_gerais = Array.from(obsSet).join('; ');
finalLaudo.problemas_criticos = Array.from(probSet);
finalLaudo.dados_refinados.observacoes_gerais = finalLaudo.observacoes_gerais;
finalLaudo.dados_refinados.problemas_criticos = finalLaudo.problemas_criticos;

return [{ json: finalLaudo }];

// COPIA EXATA do nó 'Gerar HTML do Laudo' do workflow original
// (o mesmo código que já existe - vou referenciar)
const laudoData = $input.first().json;
const dados = laudoData.dados_refinados;
const laudoId = laudoData.laudo_id;
const imovel = laudoData.imovel || 'Imóvel não identificado';
const tipoVistoria = laudoData.tipoVistoria || 'entrada';
const dataVistoria = laudoData.dataVistoria;
const dataProcessamento = laudoData.data_processamento;

const THEME = 'dark';
const LOGO_URL = 'https://example.com/assets/company-logo.png';
const COMPANY_NAME = 'Example Real Estate Company';

const dataObj = new Date(dataVistoria);
const dataFormatada = dataObj.toLocaleDateString('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' });
const dataFormatadaCurta = dataObj.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' });
const dataGeracao = new Date(dataProcessamento).toLocaleDateString('pt-BR');
const horaGeracao = new Date(dataProcessamento).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });

const endereco = laudoData.endereco || '—';
const proprietario = laudoData.proprietario || '—';
const inquilino = laudoData.inquilino || '—';

const totalComodos = dados.comodos ? dados.comodos.length : 0;
let totalItens = 0, itensProblematicos = 0, itensBom = 0, itensRegular = 0, itensNovo = 0;
if (dados.comodos) {
  dados.comodos.forEach(c => {
    if (c.itens) {
      totalItens += c.itens.length;
      c.itens.forEach(i => {
        const estado = (i.estado || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        if (['ruim', 'critico', 'pessimo', 'danificado'].includes(estado)) itensProblematicos++;
        else if (['bom'].includes(estado)) itensBom++;
        else if (['regular', 'incompleto'].includes(estado)) itensRegular++;
        else if (['novo'].includes(estado)) itensNovo++;
      });
    }
  });
}
const totalProblemas = dados.problemas_criticos ? dados.problemas_criticos.length : 0;
const score = totalItens > 0 ? Math.max(0, Math.min(100, Math.round(((totalItens - itensProblematicos) / totalItens) * 100))) : 100;

// Simplified HTML generation (same structure as original)
const tipoLabel = tipoVistoria.charAt(0).toUpperCase() + tipoVistoria.slice(1);
const scoreColor = score >= 80 ? '#4ade80' : score >= 60 ? '#fbbf24' : '#f87171';
const laudoUrl = `https://inspections.example.com/laudo/${laudoId}`;
const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(laudoUrl)}&bgcolor=1e2023&color=f0f0f0&format=png`;

function getBadge(estado) {
  if (!estado) return '<span style="padding:3px 10px;border-radius:6px;font-size:9px;font-weight:700;background:rgba(108,117,125,0.12);color:#9ca3af;">N/D</span>';
  const e = estado.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  let bg, color;
  if (e === 'novo') { bg = 'rgba(74,222,128,0.12)'; color = '#4ade80'; }
  else if (e === 'bom') { bg = 'rgba(96,165,250,0.12)'; color = '#60a5fa'; }
  else if (e === 'regular' || e === 'incompleto') { bg = 'rgba(251,191,36,0.12)'; color = '#fbbf24'; }
  else if (e === 'ruim') { bg = 'rgba(251,146,60,0.12)'; color = '#fb923c'; }
  else { bg = 'rgba(248,113,113,0.12)'; color = '#f87171'; }
  return `<span style="padding:3px 10px;border-radius:6px;font-size:9px;font-weight:700;background:${bg};color:${color};text-transform:uppercase;">${estado}</span>`;
}

let comodosHtml = '';
if (dados.comodos) {
  dados.comodos.forEach(comodo => {
    comodosHtml += `<div style="margin-bottom:28px;page-break-inside:avoid;">`;
    comodosHtml += `<div style="padding:14px 18px;background:#252528;border-radius:12px 12px 0 0;color:#fff;"><span style="font-size:14px;font-weight:700;">${comodo.nome || 'Ambiente'}</span><span style="margin-left:auto;font-size:11px;background:rgba(255,255,255,0.1);padding:4px 12px;border-radius:20px;float:right;">${comodo.itens ? comodo.itens.length : 0} itens</span></div>`;
    if (comodo.itens && comodo.itens.length > 0) {
      comodo.itens.forEach((item, i) => {
        const isLast = i === comodo.itens.length - 1;
        const obs = item.observacoes || '';
        comodosHtml += `<div style="border:1px solid #2a2a2e;border-top:none;padding:16px 20px;background:#1a1a1e;${isLast ? 'border-radius:0 0 12px 12px;' : ''}">`;
        comodosHtml += `<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:${obs ? '10px' : '0'};flex-wrap:wrap;gap:8px;">`;
        comodosHtml += `<span style="font-size:13px;font-weight:700;color:#f0f0f0;">${item.item || '—'}</span>`;
        comodosHtml += `<div style="display:flex;gap:6px;align-items:center;">`;
        if (item.tipo || item.cor) comodosHtml += `<span style="font-size:10px;color:#6a6a6e;font-style:italic;">${[item.tipo, item.cor].filter(Boolean).join(' · ')}</span>`;
        comodosHtml += getBadge(item.estado);
        comodosHtml += `</div></div>`;
        if (obs) comodosHtml += `<div style="font-size:11px;color:#a0a0a4;line-height:1.7;padding:10px 14px;background:rgba(201,169,110,0.12);border-radius:8px;border-left:3px solid #c9a96e;">${obs}</div>`;
        comodosHtml += `</div>`;
      });
    }
    comodosHtml += `</div>`;
  });
}

let problemasHtml = '';
if (dados.problemas_criticos && dados.problemas_criticos.length > 0) {
  problemasHtml = `<div style="margin-bottom:28px;"><div style="padding:20px 24px;background:rgba(248,113,113,0.12);border:1px solid rgba(248,113,113,0.3);border-radius:12px;">`;
  dados.problemas_criticos.forEach(p => {
    problemasHtml += `<div style="display:flex;gap:14px;padding:14px 0;border-bottom:1px solid #2a2a2e;align-items:flex-start;"><div style="width:28px;height:28px;background:rgba(248,113,113,0.12);color:#f87171;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;flex-shrink:0;">!</div><div style="font-size:12px;color:#a0a0a4;line-height:1.7;padding-top:5px;">${p}</div></div>`;
  });
  problemasHtml += `</div></div>`;
}

