iv></div><div style="padding:14px 18px;background:#252528;border-radius:10px;border:1px solid #2a2a2e;"><div style="font-size:9px;font-weight:700;color:#6a6a6e;text-transform:uppercase;margin-bottom:4px;">Tipo</div><div style="font-size:14px;font-weight:600;color:#f0f0f0;">${tipoLabel}</div></div><div style="padding:14px 18px;background:#252528;border-radius:10px;border:1px solid #2a2a2e;grid-column:1/-1;"><div style="font-size:9px;font-weight:700;color:#6a6a6e;text-transform:uppercase;margin-bottom:4px;">Endereço</div><div style="font-size:14px;font-weight:600;color:#f0f0f0;">${endereco}</div></div><div style="padding:14px 18px;background:#252528;border-radius:10px;border:1px solid #2a2a2e;"><div style="font-size:9px;font-weight:700;color:#6a6a6e;text-transform:uppercase;margin-bottom:4px;">Proprietário</div><div style="font-size:14px;font-weight:600;color:#f0f0f0;">${proprietario}</div></div><div style="padding:14px 18px;background:#252528;border-radius:10px;border:1px solid #2a2a2e;"><div style="font-size:9px;font-weight:700;color:#6a6a6e;text-transform:uppercase;margin-bottom:4px;">Inquilino/Comprador</div><div style="font-size:14px;font-weight:600;color:#f0f0f0;">${inquilino}</div></div></div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:28px;"><div style="padding:20px;background:#252528;border-radius:12px;border:1px solid #2a2a2e;text-align:center;"><div style="font-size:32px;font-weight:800;color:#f0f0f0;">${totalComodos}</div><div style="font-size:10px;color:#6a6a6e;text-transform:uppercase;">Ambientes</div></div><div style="padding:20px;background:#252528;border-radius:12px;border:1px solid #2a2a2e;text-align:center;"><div style="font-size:32px;font-weight:800;color:#f0f0f0;">${totalItens}</div><div style="font-size:10px;color:#6a6a6e;text-transform:uppercase;">Itens</div></div><div style="padding:20px;background:rgba(248,113,113,0.12);border-radius:12px;border:1px solid rgba(248,113,113,0.3);text-align:center;"><div st