// Limpar arquivos da sessão após processamento
const fs = require('fs');
const path = require('path');
const item = $input.first().json;
const sessionId = $('Inicializar Sessão').first().json.sessionId;
const sessionPath = `/data/inspections/sessions/${sessionId}`;

try {
  const files = fs.readdirSync(sessionPath);
  files.forEach(f => fs.unlinkSync(path.join(sessionPath, f)));
  fs.rmdirSync(sessionPath);
} catch(e) { /* ignore */ }

return [{ json: { done: true, laudo_id: item.laudo_id || $('Consolidar Laudo Final').first().json.laudo_id } }];

const fileUri = $input.first().json.file.uri;
const fileName = $input.first().json.file.name;

// ⚠️ COLOQUE SUA API KEY REAL AQUI
const apiKey = $env.GEMINI_API_KEY;

const maxAttempts = 60; // máximo 60 tentativas (5 min total)
const delayMs = 5000;

for (let i = 0; i < maxAttempts; i++) {
  let response;

  try {
    response = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://generativelanguage.googleapis.com/v1beta/${fileName}?key=${apiKey}`,
      timeout: 10000, // timeout de 10 segundos
    });
  } catch (error) {
    // Se deu erro na requisição, loga e tenta novamente
    if (i >= maxAttempts - 1) {
      throw new Error(`Polling falhou após ${maxAttempts} tentativas. Último erro: ${error.message}`);
    }
    await new Promise(resolve => setTimeout(resolve, delayMs));
    continue;
  }

  // Verificar o state (pode estar em response.state ou response.file.state)
  const state = response?.state || response?.file?.state;

  if (state === 'ACTIVE') {
    return [{
      json: {
        ...$input.first().json,
        fileState: 'ACTIVE',
        attempts: i + 1
      }
    }];
  }

  if (state === 'FAILED') {
    throw new Error(`Processamento falhou no Gemini: ${JSON.stringify(response)}`);
  }

  // Se state é undefined/null (resposta inesperada), logar e sair
  if (!state) {
    throw new Error(`Resposta inesperada da API (state undefined). Response: ${JSON.stringify(response).substring(0, 500)}`);
  }

  // state é PROCESSING, aguardar
  await new Promise(resolve => setTimeout(resolve, delayMs));
}

throw new Error(`Arquivo não ficou ACTIVE após ${maxAttempts} tentativas (${maxAttempts * delayMs / 1000}s)`);

